<script setup lang="ts">
const { data } = await useWorkspace()
const search = ref(''), filter = ref('all')
const filtered = computed(() => data.value.runs.filter(r => (filter.value === 'all' || r.status === filter.value) && r.name.toLowerCase().includes(search.value.toLowerCase())))
</script>
<template><div class="page-heading"><div><span class="eyebrow">BUILD. MEASURE. REPEAT.</span><h1>Experiments<span class="title-dot">.</span></h1><p>Keep the configuration. Learn from every iteration.</p></div><div class="button-group"><NuxtLink to="/runs/compare" class="button secondary"><AppIcon name="GitBranch" :size="16" />Compare</NuxtLink><NuxtLink to="/runs/new" class="button primary"><AppIcon name="Plus" />New experiment</NuxtLink></div></div><div class="toolbar"><div class="tabs"><button v-for="s in ['all', 'running', 'queued', 'completed', 'failed']" :key="s" :class="{ selected: filter === s }" @click="filter = s">{{ s }}<span v-if="s === 'all'">{{ data.runs.length }}</span></button></div><label class="search-box"><AppIcon name="Search" :size="17" /><input v-model="search" aria-label="Search experiments" placeholder="Find an experiment…" /></label></div><section class="panel"><RunTable v-if="filtered.length" :runs="filtered" /><EmptyState v-else icon="FlaskConical" :title="data.runs.length ? 'No experiments match your filters' : 'Make your first hypothesis'" :description="data.runs.length ? 'Choose another status or search term.' : 'Start with a model and a dataset. ForgeLabs keeps track of what comes next.'"><NuxtLink v-if="!data.runs.length" to="/runs/new" class="button secondary">Create experiment<AppIcon name="ArrowRight" :size="16" /></NuxtLink></EmptyState></section></template>
